'use strict';

/**
* Xorshift128+ pseudorandom number generator.
*
* @module @stdlib/random/base/xorshift128
*
* @example
* var xorshift128 = require( '@stdlib/random/base/xorshift128' );
*
* // Create a PRNG with a seed
* var rng = xorshift128( { seed: 12345n } );
* // returns <Function>
*
* var v = rng();
* // returns <bigint>
*
* @example
* var xorshift128 = require( '@stdlib/random/base/xorshift128' );
*
* // Without arguments, creates with random seed
* var rng = xorshift128();
* // returns <Function>
*
* var v = rng();
* // returns <bigint>
*/

// MODULES //

var factory = require( './factory.js' );


// EXPORTS //

module.exports = factory;
